import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { isLoggedIn } from "../utils/auth";

function BookAppointment() {
  const { doctorId } = useParams();

  const [doctor, setDoctor] = useState(null);
  const [selectedDate, setSelectedDate] = useState("");
  const [selectedTime, setSelectedTime] = useState("");

  // Dummy doctor data (same as list)
  const doctors = [
    {
      id: "1",
      name: "Dr. Sharma",
      specialization: "Cardiologist",
      image: "https://randomuser.me/api/portraits/men/75.jpg",
    },
    {
      id: "2",
      name: "Dr. Verma",
      specialization: "Dermatologist",
      image: "https://randomuser.me/api/portraits/women/65.jpg",
    },
  ];

  // Dummy time slots
  const timeSlots = [
    "10:00 AM",
    "11:00 AM",
    "12:00 PM",
    "02:00 PM",
    "04:00 PM",
  ];

  useEffect(() => {
    const doc = doctors.find((d) => d.id === doctorId);
    setDoctor(doc);
  }, [doctorId]);

const handleBooking = () => {
  // 🔴 Check login first
  if (!isLoggedIn()) {
    alert("Please login first");
    navigate("/login");
    return;
  }

  if (!selectedDate || !selectedTime) {
    alert("Please select date and time");
    return;
  }

  console.log({
    doctorId,
    selectedDate,
    selectedTime,
  });

  alert("Appointment Booked (Dummy)");
};

  if (!doctor) return <h3>Doctor not found</h3>;

  return (
    <div style={styles.container}>
      {/* Doctor Info */}
      <div style={styles.card}>
        <img src={doctor.image} alt="doctor" style={styles.image} />
        <h2>{doctor.name}</h2>
        <p>{doctor.specialization}</p>
      </div>

      {/* Booking Section */}
      <div style={styles.booking}>
        <h3>Select Date</h3>
        <input
          type="date"
          onChange={(e) => setSelectedDate(e.target.value)}
        />

        <h3>Select Time</h3>
        <div style={styles.slots}>
          {timeSlots.map((time) => (
            <button
              key={time}
              style={
                selectedTime === time
                  ? styles.selectedSlot
                  : styles.slot
              }
              onClick={() => setSelectedTime(time)}
            >
              {time}
            </button>
          ))}
        </div>

        <button style={styles.bookBtn} onClick={handleBooking}>
          Confirm Booking
        </button>
      </div>
    </div>
  );
}

const styles = {
  container: {
    padding: "20px",
  },
  card: {
    textAlign: "center",
    marginBottom: "20px",
  },
  image: {
    width: "100px",
    borderRadius: "50%",
  },
  booking: {
    textAlign: "center",
  },
  slots: {
    display: "flex",
    justifyContent: "center",
    gap: "10px",
    flexWrap: "wrap",
    margin: "10px 0",
  },
  slot: {
    padding: "8px 12px",
    border: "1px solid #1976d2",
    background: "#fff",
    cursor: "pointer",
    borderRadius: "5px",
  },
  selectedSlot: {
    padding: "8px 12px",
    border: "1px solid #1976d2",
    background: "#1976d2",
    color: "#fff",
    cursor: "pointer",
    borderRadius: "5px",
  },
  bookBtn: {
    marginTop: "15px",
    padding: "10px 20px",
    background: "green",
    color: "#fff",
    border: "none",
    borderRadius: "5px",
    cursor: "pointer",
  },
};

export default BookAppointment;
